head.script:
scwin.onpageload = function() {
	// 1. noResult=useData 에서 setValue 로 새 값 설정
	auto1.setValue("abc");
	window.checkLog1 = auto1.getValue();
	// 2. DataList 컬럼 ref 에서 컬럼 값 변경
	dataList1.insertRow(0);
	dataList1.setRowPosition(0);
	dataList1.setCellData(0, "col1", "abc");
	window.checkLog2 = auto2.getValue();
	// 3. DataMap ref 에서 값 변경
	dataMap1.set("key1", "abc");
	window.checkLog3 = auto3.getValue();
};
scwin.checkVal1 = function() {
	const checkVal1 = window.checkLog1 == 'abc';
	const checkVal2 = window.checkLog2 == 'abc';
	const checkVal3 = window.checkLog3 == 'abc';
	return checkVal1 && checkVal2 && checkVal3;
};
scwin.checkVal2 = function() {
	const checkVal1 = (document.getElementById('auto1_label') || document.getElementById('mf_auto1_label')).innerText == 'abc';
	const checkVal2 = (document.getElementById('auto2_label') || document.getElementById('mf_auto2_label')).innerText == 'abc';
	const checkVal3 = (document.getElementById('auto3_label') || document.getElementById('mf_auto3_label')).innerText == 'abc';
	return checkVal1 && checkVal2 && checkVal3;
};
